declare eid uuid; c jsonb := $j${"schemaVersion":1,"id":"ego-check","title":"Who is in Control?","tagline":"Who's driving today: you, or your autopilot?","emoji":"🪞🚗","category":"reflection","description":"Ten everyday work moments, a few seconds each. Go with your first instinct, then look in a private mirror: are you behind the wheel, or are your reflexes driving? The group sees only an anonymous team score.","durationMin":12,"players":{"min":5,"max":80},"languages":["en"],"ageRating":"16+","facilitator":"optional","modes":["live","self","practice"],"defaultTiming":{"readSec":5,"answerSec":5},"reveal":"none","privacy":{"individualResults":true,"groupMinimum":5,"retainResponses":false},"scoring":{"kind":"behaviour","minAnsweredRatio":0.7},"results":[{"min":0,"max":25,"emoji":"🧘","title":"You're in the driver's seat!","message":"You stay calm and open, even when it stings. Keep it up!","explanation":"Your answers show curiosity, humility and openness — even in moments that sting.","groupTitle":"We're in the driver's seat!","groupMessage":"As a team we stay open, even in tricky moments.","tone":"great"},{"min":26,"max":50,"emoji":"😎","title":"You're mostly in control!","message":"Now and then your autopilot reaches for the wheel, but you usually stay in charge.","explanation":"Most of your reactions are open and collaborative. A few situations pull you towards defending or proving yourself — which is very human.","groupTitle":"We're mostly in control!","groupMessage":"Most of the time, we choose how we react.","tone":"good"},{"min":51,"max":75,"emoji":"🦙","title":"Your autopilot grabs the wheel sometimes","message":"In some situations your first reflex takes over. The good news? You can take back control.","explanation":"In several situations your first reflex protected your position or your credit. Noticing that is the hardest part — and you just did.","groupTitle":"Our autopilot grabs the wheel sometimes","groupMessage":"Our reflexes take over now and then. Good thing we're noticing.","tone":"watch"},{"min":76,"max":100,"emoji":"👑","title":"Your autopilot is driving today","message":"Your quick reflexes may be steering more often than you realise. Time to take back the wheel!","explanation":"Today your quick reactions leaned towards defending, convincing or claiming credit. That says more about fast reflexes than about who you are — and reflexes can be retrained.","groupTitle":"Our autopilot is driving today","groupMessage":"Our reflexes did a lot of the driving. Let's take back the wheel together.","tone":"grow"}],"insights":{"themes":{"feedback":{"label":"Feedback","strength":"You stay open when your work is criticised.","growth":"Criticism can put you on the defensive quickly.","habit":"When feedback comes, ask one question before you answer.","challenge":"Ask one colleague: \"What's one thing I could do better?\" Just listen."},"credit":{"label":"Recognition","strength":"You can celebrate a colleague's win without keeping score.","growth":"Credit for shared work matters a lot to you.","habit":"Name one colleague's contribution out loud each week.","challenge":"Thank someone publicly for help they gave you this month."},"mistake":{"label":"Mistakes","strength":"You own your mistakes openly.","growth":"A mistake can make you look elsewhere first.","habit":"Say \"that one's on me\" early, then share the fix.","challenge":"Share one small mistake with your team and what you learned."},"disagree":{"label":"Disagreement","strength":"You get curious when people disagree with you.","growth":"Disagreement can switch you into convincing mode.","habit":"Before you reply, sum up their view in one sentence.","challenge":"In your next disagreement, ask \"What am I missing?\" first."},"idea":{"label":"Better ideas","strength":"You let the best idea win, whoever had it.","growth":"Letting go of your own idea is hard.","habit":"Ask \"which option is best for the client?\" instead of \"whose idea?\"","challenge":"Build on someone else's idea in your next meeting."},"change":{"label":"Change requests","strength":"You focus on the outcome, not on your pride.","growth":"Change requests can feel personal.","habit":"Ask \"what outcome do you need?\" before defending the work.","challenge":"When asked for a change, ask about the goal before you react."},"interrupt":{"label":"Interruptions","strength":"You hold your ground calmly when interrupted.","growth":"Interruptions can trigger a counter-attack.","habit":"Try \"Let me finish this thought, then I'm all ears.\"","challenge":"Notice one moment you want to interrupt — and wait three seconds."},"teamwin":{"label":"Team wins","strength":"Shared wins are enough for you.","growth":"Being left unmentioned can spoil a good moment.","habit":"Celebrate the team result first; raise credit 1:1 later if it matters.","challenge":"Congratulate the team on a win and leave yourself out of it."},"unknown":{"label":"Not knowing","strength":"You are comfortable saying \"I don't know\".","growth":"Not knowing can feel like losing face.","habit":"Practise \"I don't know yet — I'll find out.\"","challenge":"Say \"I don't know\" at least once tomorrow — and follow up."},"decision":{"label":"Team decisions","strength":"You commit once the team decides.","growth":"Letting go after a decision takes real effort.","habit":"Once a decision is made, write down one way you'll help it work.","challenge":"Help move forward one decision you didn't agree with."}},"defaultHabit":"Keep asking \"what am I missing?\" in meetings. It keeps you in the driver's seat.","defaultChallenge":"Ask one colleague how you could support them better this week."},"transitions":["Interesting… some reflexes are getting nervous! 👀","The mirror saw that. 🪞","Hands on the wheel, everyone. 🚗","Hmm… was that you or your autopilot? 🤔","Green light — keep going! 🚦","Somebody check the rear-view mirror. 👀","The llama is watching. 🦙","Seatbelts on — next one is tricky. 🔒","Nobody saw your answer. Only you. 🤫","Finish line! 🏁"],"closing":{"questions":["When does my autopilot take the wheel?","How can I notice it earlier?","What can I do differently tomorrow?"],"message":"Reflexes are human. Just don't let them drive every meeting. 🚗💜"},"disclaimer":"A light-hearted reflection game, not a psychological assessment or a performance tool. Feelings never count against you, only reactions do.","creator":"Remotecoders","status":"published","rounds":[{"id":"main","activities":[{"id":"q1","prompt":"Someone criticises your work in a meeting. What happens first?","theme":"feedback","type":"choice","options":[{"id":"a","text":"I defend it straight away.","points":3},{"id":"b","text":"I nod, but quietly decide they are wrong.","points":2},{"id":"c","text":"It stings, but I hear them out.","points":0},{"id":"d","text":"I ask what they would change.","points":0}],"shuffle":true},{"id":"q2","prompt":"A colleague is praised for something you helped with.","theme":"credit","type":"choice","options":[{"id":"a","text":"It bothers me for the rest of the day.","points":2},{"id":"b","text":"I jump in to mention my part.","points":3},{"id":"c","text":"I'm genuinely happy for them.","points":0},{"id":"d","text":"A bit disappointed, then I move on.","points":0}],"shuffle":true},{"id":"q3","prompt":"You realise you made a mistake.","theme":"mistake","type":"choice","options":[{"id":"a","text":"I flag it and start fixing it.","points":0},{"id":"b","text":"I first check who else was involved.","points":2},{"id":"c","text":"I fix it quietly and hope nobody notices.","points":3},{"id":"d","text":"I explain what happened and own it.","points":0}],"shuffle":true},{"id":"q4","prompt":"Someone disagrees with your idea.","theme":"disagree","type":"choice","options":[{"id":"a","text":"I push harder to convince them.","points":2},{"id":"b","text":"I ask what they see that I don't.","points":0},{"id":"c","text":"I'm frustrated, but I stay open.","points":0},{"id":"d","text":"I assume they haven't understood it.","points":3}],"shuffle":true},{"id":"q5","prompt":"A colleague suggests a better approach than yours.","theme":"idea","type":"choice","options":[{"id":"a","text":"I switch to it happily.","points":0},{"id":"b","text":"I need a moment, then I come around.","points":0},{"id":"c","text":"I keep defending my original idea.","points":3},{"id":"d","text":"I agree, but keep looking for its flaws.","points":2}],"shuffle":true},{"id":"q6","prompt":"Your manager asks you to change something you worked hard on.","theme":"change","type":"choice","options":[{"id":"a","text":"I take it personally.","points":2},{"id":"b","text":"I ask what outcome they need.","points":0},{"id":"c","text":"I push back before I hear the reason.","points":3},{"id":"d","text":"I'm disappointed, but I consider it.","points":0}],"shuffle":true},{"id":"q7","prompt":"Someone interrupts you in a meeting.","theme":"interrupt","type":"choice","options":[{"id":"a","text":"I get irritated and it shows.","points":2},{"id":"b","text":"I calmly ask to finish my point.","points":0},{"id":"c","text":"I interrupt them back.","points":3},{"id":"d","text":"I let them finish, then return to my point.","points":0}],"shuffle":true},{"id":"q8","prompt":"Your team succeeds, but nobody mentions you.","theme":"teamwin","type":"choice","options":[{"id":"a","text":"It spoils the moment for me.","points":2},{"id":"b","text":"The shared win is enough for me.","points":0},{"id":"c","text":"I remind everyone what I did.","points":3},{"id":"d","text":"I notice it, then let it go.","points":0}],"shuffle":true},{"id":"q9","prompt":"Someone asks you a question and you don't know the answer.","theme":"unknown","type":"choice","options":[{"id":"a","text":"I say I don't know and offer to find out.","points":0},{"id":"b","text":"I answer anyway and sound sure.","points":3},{"id":"c","text":"I ask someone who knows more.","points":0},{"id":"d","text":"I steer the conversation elsewhere.","points":2}],"shuffle":true},{"id":"q10","prompt":"You're 